// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(address receiver, uint128 amount) public {
        vm.assume(receiver != address(this));
        vm.assume(amount > 0);
        // owner is the test contract (constructor set owner = msg.sender)
        uint256 ownerBefore = address(this).balance;
        // fund the contract so the transfer succeeds in both versions
        vm.deal(address(c), amount);
        vm.prank(address(this));
        c.sendTo(receiver, amount);
        assertTrue(address(this).balance == ownerBefore);
    }
}
